shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.test.ts'
s=open(p).read()
s=s.rstrip()
assert s.endswith('});')
s=s[:-3]+'''
  it('throws from register naming the tool when its static inputSchema is not valid JSON Schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'lookup_order',
          description: 'Look up an order',
          inputSchema: {type: 'object', required: 'orderId'},
        },
        async () => 'unreachable'
      )
    ).toThrow(/lookup_order/);
  });
});
'''
open(p,'w').write(s)
EOF
timeout 300 npx jest src/orchestration/tools/registry.test.ts 2>&1 | tail -20

python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("import {Ajv} from 'ajv';","import {Ajv} from 'ajv';\nimport type {ValidateFunction} from 'ajv';")
s=s.replace("""  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}""","""  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}""")
s=s.replace("""    const resolved = this.resolveDefinition(definition);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }""","""    const resolved = this.resolveDefinition(definition);
    const validate = typeof definition === 'function' ? undefined : this.compileSchema(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  private compileSchema(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${(error as Error).message}`);
    }
  }""")
s=s.replace("""    const validate = this.ajv.compile(this.resolveDefinition(tool.definitionSource).inputSchema);""","""    const validate = tool.validate ?? this.compileSchema(this.resolveDefinition(tool.definitionSource));""")
open(p,'w').write(s)
EOF
timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js src/orchestration/tools/registry.test.ts 2>&1 | grep -v ExperimentalWarning | tail -6
